create or replace function public.record_customer_followup_atomic(p_customer_id uuid,p_equipment_id uuid,p_channel text,p_outcome text,p_notes text,p_follow_up_at timestamptz) returns uuid language plpgsql security definer set search_path=public,private,pg_temp as $$ declare a public.users%rowtype; fid uuid; begin select * into a from public.users where auth_user_id=auth.uid() and active=true limit 1; if a.id is null or a.role not in ('owner','manager','csr_dispatch') then raise exception 'Not authorized'; end if; if not private.has_permission('manage_opportunities') then raise exception 'Permission denied'; end if; if p_customer_id is null or not exists(select 1 from public.customers where id=p_customer_id) then raise exception 'Customer required'; end if; if p_equipment_id is not null and not exists(select 1 from public.customer_equipment where id=p_equipment_id and customer_id=p_customer_id) then raise exception 'Equipment does not belong to customer'; end if; if p_channel not in ('phone','sms','email','other') then raise exception 'Invalid channel'; end if; if p_outcome not in ('no_answer','left_message','spoke_not_ready','callback','booked','declined','other') then raise exception 'Invalid outcome'; end if; if length(coalesce(p_notes,''))>3000 then raise exception 'Notes too long'; end if; insert into public.customer_followups(customer_id,equipment_id,csr_user_id,channel,outcome,notes,follow_up_at) values(p_customer_id,p_equipment_id,a.id,p_channel,p_outcome,nullif(btrim(coalesce(p_notes,'')),''),p_follow_up_at) returning id into fid; insert into public.audit_log(actor_user_id,action,entity_type,entity_id,after_data) values(a.id,'record_customer_followup','customer',p_customer_id::text,jsonb_build_object('followup_id',fid,'channel',p_channel,'outcome',p_outcome,'follow_up_at',p_follow_up_at)); return fid; end $$; revoke all on function public.record_customer_followup_atomic(uuid,uuid,text,text,text,timestamptz) from public; grant execute on function public.record_customer_followup_atomic(uuid,uuid,text,text,text,timestamptz) to authenticated;